function fontCard(g){const supported=fontSupported(g);return `<section class="card font-card"><div class="card-header"><div><h2>${icon('edit')}替换字体</h2><p>为这个游戏单独选择文字字体。</p></div></div><div class="font-current"><small>当前设置</small><strong>${esc(fontSummary(g))}</strong></div><p class="card-description">${supported?(g.engine==='Unreal Engine'?'使用游戏内 Font 资源，作用于适配器回填的文字。':'适配器加载所选字体，具体控件和字符覆盖需在游戏中验证。'):g.capability==='experimental-hook'?'浮窗与内嵌字体在“Galgame 文本 Hook → 字体与显示”中设置。':'此引擎尚未提供字体适配。'}</p>${tmpReportMarkup(g.font?.tmpReport)}<div class="adapter-actions">${g.engine==='Unity'?`<button class="btn" data-action="legacy-cache" data-id="${esc(g.id)}" ${g.adapterStatus==='installed'?'disabled':''}>${icon('folder')}旧译文缓存</button>`:''}<button class="btn" data-action="game-font" data-id="${esc(g.id)}" ${supported?'':'disabled'}>${icon('edit')}替换字体</button></div></section>`;}
