  if(action==='library-view'){state.view=button.dataset.value;localStorage.setItem('libraryView',state.view);renderLibrary();return;}
  if(action==='add-provider'){showProvider();return;}
  if(action==='edit-provider'){showProvider(providerById(id)||{});return;}
  if(action==='translate-test'){showTranslate();return;}
  if(action==='edit-translation'){showTranslationEdit(id);return;}
  if(action==='add-term'){showTerm();return;}
  if(action==='edit-term'){showTerm(main._glossaryItems?.find(t=>t.id===id)||{});return;}
  if(action==='translation-page'){state.translationPage=Number(button.dataset.value);await renderTranslations();return;}
