function checkDirty(){if(state.updateInProgress)return false;if(state.dirty&&!confirm('当前设置尚未保存，确定离开页面吗？'))return false;state.dirty=false;return true;}
document.addEventListener('click',event=>{const link=event.target.closest('a[href^="#"]');if(link&&!checkDirty())event.preventDefault();});
document.addEventListener('keydown',event=>{if(event.key==='Escape'){if(document.getElementById('modal-root').childElementCount)closeModal();else{document.getElementById('sidebar').classList.remove('open');document.getElementById('sidebar-backdrop').classList.remove('open');}}if(event.key==='Enter'&&event.target.matches('.game-card,.game-row')){event.preventDefault();event.target.click();}if(event.key==='Tab'&&document.getElementById('modal-root').childElementCount){const dialog=document.querySelector('.modal');const focusables=[...dialog.querySelectorAll('button,input,select,textarea,a[href]')].filter(el=>!el.disabled&&el.offsetParent!==null),first=focusables[0],last=focusables[focusables.length-1];if(event.shiftKey&&(document.activeElement===first||document.activeElement===dialog)){event.preventDefault();last?.focus();}else if(!event.shiftKey&&document.activeElement===last){event.preventDefault();first?.focus();}}});
document.getElementById('sidebar-backdrop').onclick=()=>{document.getElementById('sidebar').classList.remove('open');document.getElementById('sidebar-backdrop').classList.remove('open');};
window.addEventListener('hashchange',()=>{if(!checkDirty()){history.replaceState(null,'',renderedHash||'#library');return;}renderedHash=location.hash;state.translationPage=1;render();});
window.addEventListener('beforeunload',e=>{if(state.dirty||modalDirty){e.preventDefault();e.returnValue='';}});
let dragDepth=0;document.addEventListener('dragenter',e=>{if(e.dataTransfer?.types.includes('Files')){e.preventDefault();dragDepth++;document.body.classList.add('drop-active');}});document.addEventListener('dragleave',()=>{if(--dragDepth<=0){dragDepth=0;document.body.classList.remove('drop-active');}});document.addEventListener('dragover',e=>{if(e.dataTransfer?.types.includes('Files'))e.preventDefault();});document.addEventListener('drop',e=>{if(!e.dataTransfer?.files.length)return;e.preventDefault();dragDepth=0;document.body.classList.remove('drop-active');const file=e.dataTransfer.files[0];if(file.path){showAddGame(file.path);}else{showAddGame();toast('浏览器无法读取拖入文件的完整路径，请点击「选择」或粘贴路径','info');}});
async function start(){try{const response=await fetch('/api/session',{credentials:'same-origin',cache:'no-store'});if(!response.ok)throw new Error('无法连接本机服务');const session=await response.json();state.token=session.token;await refreshBootstrap();await render();}catch(e){main.innerHTML=`${pageHead('打开工作空间','连接本机游戏翻译服务。')}${empty('本机服务连接失败',`${esc(e.message)}。请保持启动程序运行后刷新页面。`,'<button class="btn primary" onclick="location.reload()">重新连接</button>','warning')}`;}}
start();
